item.stdout:
//! Read-only durable release interfaces.
//!
//! Planning deliberately accepts only exact package identities. It never
//! accepts an inline intent or searches for an authority file. Execution is
//! intentionally not wired until the provider adapter can prove exact remote
//! identities; exposing a permissive fallback here would recreate the legacy
//! publish/tag bypass this command family replaces.

use std::process::ExitCode;

use callisto_graph::commands::{
    build_release_intent, derive_release_commit_decision, derive_selected_release_decision,
    execute_release_with_artifacts, reconcile_release_execution, validate_release_intent_with_state_directory,
    verify_artifact_manifest, ReleaseStateStore, VersionOptions,
};
use callisto_graph::locate::IgnoreWalkLocator;
use callisto_model::{
    ApplyPermit, ArtifactManifestV1, ExecutionTrustProfileV1, ReleaseExecutionStateV1, ReleaseIntentV1,
    ReleasePackageId,
};

use crate::cli::{
    GlobalArgs, OutputFormat, ReleaseArgs, ReleaseExecuteArgs, ReleaseInspectArgs, ReleasePlanArgs,
    ReleaseReconcileArgs,
};
use crate::error::CliError;
use crate::output::write_json;
use crate::runner::CliCommandRunner;
use crate::workspace::{load_workspace, select_inference};

pub fn handle(args: ReleaseArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    match args {
        ReleaseArgs::Plan(args) => plan(args, global),
        ReleaseArgs::Inspect(args) => inspect(args, global),
        ReleaseArgs::Reconcile(args) => reconcile(args, global),
        ReleaseArgs::Execute(args) => execute(args, global),
    }
}

fn plan(args: ReleasePlanArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    if global.dry_run {
        return Err(CliError::Other(
            "release plan needs an output file; remove --dry-run because planning is already read-only".to_string(),
        ));
    }
    let runner = CliCommandRunner;
    let workspace = load_workspace(global, &runner)?;
    let decision = match args.from_release_commit.as_deref() {
        Some(raw) => {
            let commit = callisto_model::CommitSha::parse(raw)
                .map_err(|error| CliError::Other(format!("invalid merged release commit `{raw}`: {error}")))?;
            let decision_path = args
                .decision
                .as_deref()
                .expect("clap requires --decision alongside --from-release-commit");
            derive_release_commit_decision(&workspace, &commit, decision_path)?
        }
        None => {
            let selections = args
                .packages
                .iter()
                .map(|raw| {
                    ReleasePackageId::parse(raw).map_err(|error| {
                        CliError::Other(format!(
                            "invalid release package `{raw}`: {error}; use an exact ecosystem-qualified identity such as cargo/callisto-cli"
                        ))
                    })
                })
                .collect::<Result<Vec<_>, _>>()?;
            let inference = select_inference();
            let version_plan =
                callisto_graph::commands::plan_version(&workspace, &inference, &VersionOptions::default())?;
            derive_selected_release_decision(&workspace, &version_plan, &selections)?
        }
    };
    let locator = IgnoreWalkLocator::new(&workspace.root);
    let intent = build_release_intent(
        &workspace.root,
        &locator,
        &runner,
        &decision,
        ExecutionTrustProfileV1::GitCommit,
    )?;
    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run)
        .expect("release plan rejects --dry-run before creating its explicit output");
    write_intent(&args.out, &intent, &permit)?;
    match global.format {
        OutputFormat::Json => write_json(&mut std::io::stdout(), &intent)?,
        OutputFormat::Text => println!("Wrote release intent {} to {}", intent.digest(), args.out.display()),
    }
    Ok(ExitCode::SUCCESS)
}

fn inspect(args: ReleaseInspectArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let value = read_json_file(&args.input)?;
    match global.format {
        OutputFormat::Json => write_json(&mut std::io::stdout(), &value)?,
        OutputFormat::Text => println!(
            "{}",
            serde_json::to_string_pretty(&value).expect("JSON value serializes")
        ),
    }
    Ok(ExitCode::SUCCESS)
}

fn reconcile(args: ReleaseReconcileArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let intent = read_intent(&args.intent)?;
    let state = match args.state {
        Some(path) => ReleaseStateStore::new(path).load(&intent)?,
        None => None,
    }
    .unwrap_or_else(|| ReleaseExecutionStateV1::pending(&intent));
    let report = reconcile_release_execution(&intent, &state)?;
    match global.format {
        OutputFormat::Json => write_json(&mut std::io::stdout(), report.eligible())?,
        OutputFormat::Text => {
            for operation in report.eligible() {
                println!("eligible: {operation:?}");
            }
        }
    }
    Ok(ExitCode::SUCCESS)
}

fn execute(args: ReleaseExecuteArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let intent = read_intent(&args.intent)?;
    let manifest = args
        .artifact_manifest
        .as_deref()
        .map(read_artifact_manifest)
        .transpose()?;
    match (
        intent.artifact_slots.is_empty(),
        manifest.as_ref(),
        args.artifact_dir.as_deref(),
    ) {
        (true, None, None) => {}
        (true, _, _) => {
            return Err(CliError::Other(
                "release intent declares no binary artifact slots; omit --artifact-manifest and --artifact-dir"
                    .to_owned(),
            ));
        }
        (false, Some(manifest), Some(directory)) => {
            let runner = CliCommandRunner;
            verify_artifact_manifest(&intent, manifest, directory, &runner)?;
        }
        (false, _, _) => {
            return Err(CliError::Other(
                "release intent declares binary artifact slots; provide both --artifact-manifest and --artifact-dir"
                    .to_owned(),
            ));
        }
    }
    let runner = CliCommandRunner;
    let root = dunce::canonicalize(&global.cwd).map_err(|source| CliError::Io {
        source,
        path: Some(global.cwd.clone()),
    })?;
    let locator = IgnoreWalkLocator::new(&root);
    let explicit_state_directory = args.state.as_deref().and_then(std::path::Path::parent);
    let capability =
        validate_release_intent_with_state_directory(&root, &locator, &runner, explicit_state_directory, intent)?;
    let store = match args.state {
        Some(path) => ReleaseStateStore::new(path),
        None => ReleaseStateStore::default_for(&root, capability.intent())?,
    };
    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run).ok_or_else(|| {
        CliError::Other(
            "release execute cannot run with --dry-run; use release reconcile for a read-only readiness check"
                .to_string(),
        )
    })?;
    let state = execute_release_with_artifacts(&capability, &store, &permit, manifest.as_ref())?;
    match global.format {
        OutputFormat::Json => write_json(&mut std::io::stdout(), &state)?,
        OutputFormat::Text => println!("Release execution state saved to {}", store.path().display()),
    }
    Ok(ExitCode::SUCCESS)
}

fn read_intent(path: &std::path::Path) -> Result<ReleaseIntentV1, CliError> {
    serde_json::from_value(read_json_file(path)?)
        .map_err(|error| CliError::Other(format!("invalid release intent {}: {error}", path.display())))
}

fn read_artifact_manifest(path: &std::path::Path) -> Result<ArtifactManifestV1, CliError> {
    serde_json::from_value(read_json_file(path)?)
        .map_err(|error| CliError::Other(format!("invalid artifact manifest {}: {error}", path.display())))
}

fn read_json_file(path: &std::path::Path) -> Result<serde_json::Value, CliError> {
    let content = std::fs::read_to_string(path).map_err(|source| CliError::Io {
        source,
        path: Some(path.to_path_buf()),
    })?;
    serde_json::from_str(&content)
        .map_err(|error| CliError::Other(format!("invalid JSON in {}: {error}", path.display())))
}

fn write_intent(path: &std::path::Path, intent: &ReleaseIntentV1, permit: &ApplyPermit) -> Result<(), CliError> {
    let content = serde_json::to_string_pretty(intent).expect("release intent serializes") + "\n";
    callisto_model::atomic::atomic_write(path, &content, permit).map_err(|source| CliError::Io {
        source,
        path: Some(path.to_path_buf()),
    })?;
    Ok(())
}
name: Release

on:
  push:
    branches:
      - main
  workflow_dispatch:

permissions: {}

concurrency:
  group: release-${{ github.ref }}
  cancel-in-progress: false

jobs:
  verify:
    name: Verify release candidate
    runs-on: ubuntu-latest
    permissions:
      contents: read
    steps:
      - name: Checkout repository
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          fetch-depth: 0
          persist-credentials: false

      - name: Build local Callisto
        uses: $/.github/actions/setup-callisto
        with:
          source: local

      - name: Install just
        uses: extractions/setup-just@53165ef7e734c5c07cb06b3c8e7b647c5aa16db3 # v4.0.0
        with:
          just-version: '1.58.0'

      - name: Format Check
        run: just fmt-check

      - name: Clippy Lints
        run: just lint

      - name: Install release verification tools
        uses: taiki-e/install-action@e67fa11c4b9316fa714ddf0abed07a0c3143b95b # v2
        with:
          tool: cargo-nextest,ripgrep

      - name: Unit & Integration Tests
        run: just test

      - name: WASM Target Check
        run: just wasm-check

      - name: Install cargo-deny
        uses: taiki-e/install-action@e67fa11c4b9316fa714ddf0abed07a0c3143b95b # v2
        with:
          tool: cargo-deny

      - name: Supply Chain Audit
        run: just audit

      - name: Reject mutable GitHub Actions references
        run: .github/tests/verify-action-pins.sh

  version-pr:
    name: Create or update the Callisto release PR
    needs: verify
    runs-on: ubuntu-latest
    permissions:
      contents: write
      pull-requests: write
    outputs:
      has_pending_changesets: ${{ steps.version-pr.outputs.hasChangesets }}

    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          fetch-depth: 0
          persist-credentials: false
      - uses: $/.github/actions/setup-callisto
        with:
          source: local
      - name: Compose, version, and open the release PR
        id: version-pr
        uses: $/.github/actions/callisto-action
        with:
          setup_callisto: 'false'
          branch: main
          release_branch: callisto/version-packages
          # This workspace bumps interdependent Cargo packages together, so a
          # bumped member's own Cargo.lock entry goes stale without this --
          # see ARCHITECTURE.md's "Lockfile Staleness" section.
          version_command: 'callisto version --refresh-lockfiles'
        env:
          GH_TOKEN: ${{ github.token }}

  release-candidate:
    name: Identify a merged Callisto release PR
    needs: [verify, version-pr]
    if: needs.version-pr.outputs.has_pending_changesets == 'false'
    runs-on: ubuntu-latest
    permissions:
      contents: read
      pull-requests: read
    outputs:
      is_release_pr: ${{ steps.candidate.outputs.is_release_pr }}
    steps:
      - id: candidate
        shell: bash
        env:
          GH_TOKEN: ${{ github.token }}
        run: |
          set -euo pipefail
          # This only schedules the job. `release plan` verifies the actual
          # parent-to-merge delta; labels and PR metadata are never authority.
          # The GitHub API check is complementary provenance evidence: a
          # trusted merge must be both an actual merge of the managed PR and
          # a GitHub-verified signed commit. It cannot be a direct push.
          prs=$(gh api --paginate "/repos/${GITHUB_REPOSITORY}/commits/${GITHUB_SHA}/pulls" --jq '[.[] | select(.merged_at != null and .base.ref == "main" and (.head.ref == "callisto/version-packages" or (.head.ref | test("^callisto/version-packages--[0-9a-f]{40}$"))))] | length')
          verified=$(gh api "/repos/${GITHUB_REPOSITORY}/commits/${GITHUB_SHA}" --jq '.commit.verification.verified')
          if [[ "$prs" == 1 && "$verified" == true ]]; then
            echo 'is_release_pr=true' >> "$GITHUB_OUTPUT"
          else
            echo 'is_release_pr=false' >> "$GITHUB_OUTPUT"
          fi

  plan:
    name: Derive ephemeral intent from the merged release commit
    needs: release-candidate
    if: needs.release-candidate.outputs.is_release_pr == 'true'
    runs-on: ubuntu-latest
    permissions:
      contents: read
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          ref: ${{ github.sha }}
          fetch-depth: 0
          persist-credentials: false
      - uses: $/.github/actions/setup-callisto
        with:
          source: local
      - name: Derive and hash intent
        run: |
          set -euo pipefail
          callisto release plan --from-release-commit "$GITHUB_SHA" --decision .callisto/release-decision.json --out release-intent.json
          shasum -a 256 release-intent.json > release-intent.json.sha256
      - uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7.0.1
        with:
          name: release-intent
          path: |
            release-intent.json
            release-intent.json.sha256
          if-no-files-found: error
          retention-days: 1

  build:
    name: Build the intent-bound source tree
    needs: plan
    runs-on: ubuntu-latest
    permissions:
      contents: read
      attestations: write
      id-token: write
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          ref: ${{ github.sha }}
          fetch-depth: 0
          persist-credentials: false
      - uses: $/.github/actions/setup-callisto
        with:
          source: local
      - uses: extractions/setup-just@53165ef7e734c5c07cb06b3c8e7b647c5aa16db3 # v4.0.0
        with:
          just-version: '1.58.0'
      - uses: actions/download-artifact@3e5f45b2cfb9172054b4087a40e8e0b5a5461e7c # v8.0.1
        with:
          name: release-intent
          path: .release-handoff
      - name: Verify handoff and build
        run: |
          set -euo pipefail
          (cd .release-handoff && shasum -a 256 -c release-intent.json.sha256)
          callisto release inspect --input .release-handoff/release-intent.json
          mkdir -p release-artifacts
          just build
      - name: Attest declared binary artifacts
        if: hashFiles('release-artifacts/**') != ''
        uses: actions/attest-build-provenance@4d101475d8b20a2381f78447822ac1eab6504dd8 # v4.2.2
        with:
          subject-path: release-artifacts/**
      - uses: actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a # v7.0.1
        with:
          name: release-build
          # include-hidden-files: upload-artifact excludes dotfiles by
          # default, and .release-handoff is one -- without this it silently
          # uploads nothing and "execute" downloads an empty artifact.
          include-hidden-files: true
          path: |
            .release-handoff
            release-artifacts
          if-no-files-found: error
          retention-days: 1

  environment-policy:
    name: Verify release Environment protection
    needs: build
    runs-on: ubuntu-latest
    permissions:
      actions: read
    steps:
      - name: Require release Environment reviewers
        shell: bash
        env:
          GH_TOKEN: ${{ github.token }}
        run: |
          set -euo pipefail
          reviewers=$(gh api "/repos/${GITHUB_REPOSITORY}/environments/release" --jq '.protection_rules // [] | map(select(.type == "required_reviewers")) | length')
          [[ "$reviewers" != 0 ]] || { echo '::error::GitHub Environment release has no required-reviewers protection rule'; exit 1; }

  execute:
    name: Execute approved release
    needs: environment-policy
    runs-on: ubuntu-latest
    environment: release
    permissions:
      contents: write
      attestations: read
      id-token: write
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          ref: ${{ github.sha }}
          fetch-depth: 0
          # Unlike every other job's checkout, this one must persist
          # credentials: dispatch_tag (callisto-graph) pushes the release tag
          # with a plain `git push`, which has no other way to authenticate.
          # This job's own contents: write permission (above) is what backs it.
          persist-credentials: true
      - uses: $/.github/actions/setup-callisto
        with:
          source: local
      # Downloaded outside the workspace (under $RUNNER_TEMP, like
      # setup-callisto's own binary install): callisto release execute
      # re-checks release trust before every dispatch, which requires a
      # worktree with no tracked or untracked files -- landing these inside
      # the checkout would dirty it and fail that check before anything
      # gets published.
      - uses: actions/download-artifact@3e5f45b2cfb9172054b4087a40e8e0b5a5461e7c # v8.0.1
        with:
          name: release-intent
          path: ${{ runner.temp }}/release-intent
      - uses: actions/download-artifact@3e5f45b2cfb9172054b4087a40e8e0b5a5461e7c # v8.0.1
        with:
          name: release-build
          path: ${{ runner.temp }}/release-build
      - name: Verify same-run handoff before credentials
        run: |
          set -euo pipefail
          intent_dir="${RUNNER_TEMP}/release-intent"
          build_dir="${RUNNER_TEMP}/release-build"
          (cd "$intent_dir" && shasum -a 256 -c release-intent.json.sha256)
          # .release-handoff and release-artifacts were sibling upload paths
          # in "build", so upload-artifact rooted the archive one level up --
          # the handoff file lands here nested under .release-handoff/, not
          # flat at release-intent.json.
          cmp "$intent_dir/release-intent.json" "$build_dir/.release-handoff/release-intent.json"
      - name: Execute verified release
        env:
          CARGO_REGISTRY_TOKEN: ${{ secrets.CARGO_REGISTRY_TOKEN }}
          NPM_TOKEN: ${{ secrets.NPM_TOKEN }}
          TWINE_PASSWORD: ${{ secrets.TWINE_PASSWORD }}
          GH_TOKEN: ${{ github.token }}
        run: |
          set -euo pipefail
          intent_dir="${RUNNER_TEMP}/release-intent"
          build_dir="${RUNNER_TEMP}/release-build"
          state_dir="${RUNNER_TEMP}/callisto-release-state/${GITHUB_RUN_ID}"
          mkdir -p "$state_dir"
          args=(--intent "$intent_dir/release-intent.json" --state "$state_dir/execution-state.json")
          if [[ -f "$build_dir/release-artifacts/manifest.json" ]]; then
            args+=(--artifact-manifest "$build_dir/release-artifacts/manifest.json" --artifact-dir "$build_dir/release-artifacts")
          fi
          callisto release execute "${args[@]}"

