  2	//!
  3	//! This is deliberately separate from the executor: it observes neither Git,
  4	//! registries, nor a forge. Its only authority is one exact intent and the
  5	//! state explicitly bound to that intent.
  6	
  7	use std::collections::{BTreeMap, BTreeSet};
  8	
