 84	/// The exact pending operations which are safe for a future executor to
 85	/// consider. Being listed here does not perform an effect or bypass its
 86	/// immediately-before-effect revalidation.
 87	#[derive(Clone, Debug, PartialEq, Eq)]
 88	pub struct ReconciledReleaseExecution {
 89	    eligible: Vec<ReleaseOperationId>,
 90	}
 91	
 92	impl ReconciledReleaseExecution {
 93	    /// Operations in the intent's stable canonical order.
 94	    pub fn eligible(&self) -> &[ReleaseOperationId] {
 95	        &self.eligible
 96	    }
 97	}
 98	
 99	/// Reconciles `state` against exactly `intent` without performing any I/O.
100	///
101	/// An operation is eligible only while it is `Pending` and every *transitive*
102	/// prerequisite is exactly `Published` or `AlreadySatisfied`. `Attempting`,
103	/// missing, failed, and blocked operations are never inferred as success.
104	pub fn reconcile_release_execution(
105	    intent: &ReleaseIntentV1,
106	    state: &ReleaseExecutionStateV1,
107	) -> Result<ReconciledReleaseExecution, GraphError> {
108	    state
109	        .validate_for_intent(intent)
110	        .map_err(|source| GraphError::ReleaseExecutionState { source })?;
111	
112	    let prerequisites: BTreeMap<_, _> = intent
113	        .operations
114	        .iter()
115	        .map(|operation| (operation.id().clone(), operation.prerequisites().to_vec()))
116	        .collect();
117	
118	    let mut eligible = Vec::new();
119	    for operation in &intent.operations {
120	        if state.operation_state(operation.id()) != Some(OperationState::Pending) {
121	            continue;
122	        }
123	        let mut visited = BTreeSet::new();
124	        if prerequisites_satisfied_transitively(operation.id(), &prerequisites, state, &mut visited) {
125	            eligible.push(operation.id().clone());
126	        }
127	    }
128	    Ok(ReconciledReleaseExecution { eligible })
129	}
130	
131	fn prerequisites_satisfied_transitively(
132	    id: &ReleaseOperationId,
133	    prerequisites: &BTreeMap<ReleaseOperationId, Vec<ReleaseOperationId>>,
134	    state: &ReleaseExecutionStateV1,
135	    visited: &mut BTreeSet<ReleaseOperationId>,
136	) -> bool {
137	    // `ReleaseIntentV1` has already proved this is a DAG. Keeping the visited
138	    // guard makes this helper fail closed if a future model version violates
139	    // that invariant rather than recursing indefinitely.
140	    if !visited.insert(id.clone()) {
141	        return false;
142	    }
143	    let result = prerequisites.get(id).is_some_and(|direct| {
144	        direct.iter().all(|prerequisite| {
145	            matches!(
146	                state.operation_state(prerequisite),
147	                Some(OperationState::Published | OperationState::AlreadySatisfied)
148	            ) && prerequisites_satisfied_transitively(prerequisite, prerequisites, state, visited)
149	        })
150	    });
151	    visited.remove(id);
152	    result
153	}
